mapper.insert:
		/** qustnr-mapper.insertQustnr (설문 등록) */

        	SELECT NVL(MAX(QUSTNR_SN) + 1, 1) AS QUSTNR_SN FROM G_QESTNAR


		INSERT INTO G_QESTNAR (
			QUSTNR_SN
			,QUSTNR_SJ
			,QUSTNR_PURPS
			,QUSTNR_BGN_DE
			,QUSTNR_END_DE
			,FRST_REGISTER_ID
			,FRST_REGIST_PNTTM
			,LAST_UPDUSR_ID
			,LAST_UPDT_PNTTM
			,SRVY_TRGT
		) VALUES (
			#{qustnrSn}
			,#{qustnrSj}
			,#{qustnrPurps}
			,#{qustnrBgnDe}
			,#{qustnrEndDe}
			,#{frstRegisterId}
			,
			,#{frstRegisterId}
			,
			,#{srvyTrgt}
		)

/** qustnr-mapper.insertQustnrQesitm (질문 등록)	*/


INSERT INTO G_QUSTNR_QESITM (
	QUSTNR_SN
	,QUSTNR_QESITM_SN
	,QESTN_SN
	,QESTN_TY_CODE
	,QESTN_CN
	,ANSWER_CHOISE_CO
	,FRST_REGISTER_ID
	,FRST_REGIST_PNTTM
	,LAST_UPDUSR_ID
	,LAST_UPDT_PNTTM
	,PARENT_SN
) VALUES (
	#{qustnrSn}
	,#{qustnrQesitmSn}
	,(SELECT NVL(MAX(QESTN_SN) + 1, 1)
		FROM G_QUSTNR_QESITM
	   WHERE QUSTNR_SN = #{qustnrSn} )
	,#{qestnTyCode}
	,#{qestnCn}
	,#{answerChoiseCo}
	,#{frstRegisterId}
	,
	,#{frstRegisterId}
	,
	,#{parentSn}
)

		/** qustnr-mapper.insertQustnrQesitm (질문 등록) */

        	SELECT NVL(MAX(QUSTNR_IEM_SN) + 1, 1) AS QUSTNR_IEM_SN FROM G_QUSTNR_IEM WHERE QUSTNR_SN = #{qustnrSn} AND QUSTNR_QESITM_SN = #{qustnrQesitmSn}


		INSERT INTO G_QUSTNR_IEM (
			QUSTNR_SN
			,QUSTNR_QESITM_SN
			,QUSTNR_IEM_SN
			,IEM_SN
			,IEM_CN
			,ETC_ANSWER_AT
			,FRST_REGISTER_ID
			,FRST_REGIST_PNTTM
			,LAST_UPDUSR_ID
			,LAST_UPDT_PNTTM
		) VALUES (
			#{qustnrSn}
			,#{qustnrQesitmSn}
			,#{qustnrIemSn}
			,(SELECT NVL(MAX(IEM_SN) + 1, 1)
				FROM G_QUSTNR_IEM
			   WHERE QUSTNR_SN = #{qustnrSn}
			     AND QUSTNR_QESITM_SN = #{qustnrQesitmSn} )
			,#{iemCn}
			,#{etcAnswerAt}
			,#{frstRegisterId}
			,
			,#{frstRegisterId}
			,
		)

